"""Independent battery thermal learning stages and portfolio card."""
from pathlib import Path

def publish_pages(root):
    root=Path(root)
    for name in ['battery-thermal.html','battery-thermal-cad.html','battery-thermal-stage-02.html','battery-thermal-stage-03.html','battery-thermal-stage-04.html','battery-thermal-stage-05.html']:
        (root/'AISolutions'/name).write_text((root/'scripts/content'/name).read_text())

def battery_thermal_card():
    return '''<article class="simulation-card filter-item" id="battery-thermal" data-category="Thermal" data-method="systems" data-analysis-company-ids="independent-work"><div class="card-copy"><p class="eyebrow">Independent work / Battery thermal modeling</p><h2>Battery thermal modeling, step by step</h2><p>Start with one cell, then build a coupled PCB and enclosure model. The latest stage adds bonded graphite to spread RF-pad heat, comparing the cover hot spot, warm area and a matched conductivity control.</p><div class="pills"><span>FreeCAD</span><span>Python</span><span>SciPy</span><span>Open source</span></div><p class="study-note">Stages 01–05 available · Graphite-spreader comparison · Layered finite volumes and lumped packages · Assumed inputs · Numerically verified, not experimentally validated.</p></div><a class="analysis-research-image" href="/AISolutions/battery-thermal-stage-05.html" aria-label="Open the graphite spreader thermal comparison"><img src="/assets/studies/battery-thermal/stage-05/figures/cover_comparison.png" alt="Back-cover temperature maps for pad only, graphite spreader and a matched low-lateral-conductivity control" loading="lazy" width="1870" height="1020"></a><div class="card-bottom"><a class="text-link" href="/AISolutions/battery-thermal.html">Start with Stage 01 →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-02.html">Compare heat input →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-03.html">Explore PCB &amp; enclosure →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-04.html">Compare the RF cooling pad →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-05.html">Explore graphite spreading →</a></div></article>'''
